CREATE TABLE USERS (
  USER_ID NUMBER(10) CONSTRAINT PK_USERS PRIMARY KEY,
  FULL_NAME VARCHAR2(120) NOT NULL,
  EMAIL VARCHAR2(200) NOT NULL CONSTRAINT UQ_USERS_EMAIL UNIQUE,
  CITY VARCHAR2(80) NOT NULL,
  JOINED_DATE DATE NOT NULL
);

CREATE TABLE CLAIMS (
  CLAIM_ID NUMBER(10) CONSTRAINT PK_CLAIMS PRIMARY KEY,
  USER_ID NUMBER(10) NOT NULL,
  POLICY_NO VARCHAR2(40) NOT NULL,
  CLAIM_TYPE VARCHAR2(30) NOT NULL,
  CLAIM_AMOUNT NUMBER(12,2) NOT NULL,
  CLAIM_STATUS VARCHAR2(20) NOT NULL,
  FILED_DATE DATE NOT NULL,
  SETTLED_DATE DATE,
  CONSTRAINT FK_CLAIMS_USERS FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID),
  CONSTRAINT CK_CLAIMS_AMOUNT CHECK (CLAIM_AMOUNT >= 0),
  CONSTRAINT CK_CLAIMS_STATUS CHECK (CLAIM_STATUS IN ('PENDING','APPROVED','REJECTED','PAID','CLOSED'))
);

CREATE INDEX IX_CLAIMS_USER ON CLAIMS(USER_ID);
CREATE INDEX IX_CLAIMS_STATUS ON CLAIMS(CLAIM_STATUS);



